bank=[]
for i,line in enumerate(rows.splitlines(),101):
    subject,chapter,number,page,prompt,correct,d1,d2,d3,explanation,memory=line.split('|')
    options=[correct,d1,d2,d3]
    answer=(i-1)%4
    options.insert(answer,options.pop(0))
    bank.append(dict(id=i,subject=subject,category=subject+' · '+chapter,bookRef=f'LF MU · {subject} · {chapter} {number} · str. {page}',sourcePages=page,sourceItem=number,question=prompt,options=options,answer=answer,title=correct,paragraphs=[explanation],memory=memory))
assert len(bank)==50 and bank[-1]['id']==150
assert [sum(q['subject']==s for q in bank) for s in ('Fyzika','Chemie','Biologie')]==[25,13,12]
for q in bank: assert len(set(q['options']))==4 and q['options'][q['answer']]==q['title']
Path(__file__).with_name('muni-101-150.json').write_text(json.dumps(bank,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
